export const getCompleteEmailSignInUrl = (params: CompleteEmailSignInParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/auth/email/verify?${stringifiedParams}` : `/api/auth/email/verify`
}

/**
 * @summary Verify the magic-link token, claim alert subscription, redirect to sign-in
 */
export const completeEmailSignIn = async (params: CompleteEmailSignInParams, options?: Parameters<typeof customFetch>[1]): Promise<unknown> => {

  return customFetch<unknown>(getCompleteEmailSignInUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getCompleteEmailSignInQueryKey = (params?: CompleteEmailSignInParams,) => {
    return [
    `/api/auth/email/verify`, ...(params ? [params] : [])
    ] as const;
    }


export const getCompleteEmailSignInQueryOptions = <TData = Awaited<ReturnType<typeof completeEmailSignIn>>, TError = ErrorType<void>>(params: CompleteEmailSignInParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof completeEmailSignIn>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getCompleteEmailSignInQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof completeEmailSignIn>>> = ({ signal }) => completeEmailSignIn(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof completeEmailSignIn>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

